using Quiz.Domain.Questions;

namespace Quiz.Infrastructure.Persistence.Configurations;

/// <summary>
/// Расширенный банк вопросов уровня Senior и Senior+.
/// </summary>
internal static class SeniorQuestionSeed
{
    private const int ExpectedQuestionsPerTopic = 35;

    public static object[] All =>
    [
        .. Create(Topic.CSharp, 1, CSharpQuestions),
        .. Create(Topic.EntityFramework, 2, EntityFrameworkQuestions),
        .. Create(Topic.RabbitMQ, 3, RabbitMqQuestions),
        .. Create(Topic.PostgreSQL, 4, PostgreSqlQuestions),
        .. Create(Topic.Architecture, 5, ArchitectureQuestions)
    ];

    private static IEnumerable<object> Create(
        Topic topic,
        int topicNumber,
        IReadOnlyCollection<(string Text, string IdealAnswer)> questions)
    {
        if (questions.Count != ExpectedQuestionsPerTopic)
        {
            throw new InvalidOperationException(
                $"Topic {topic} must contain exactly {ExpectedQuestionsPerTopic} additional questions.");
        }

        return questions.Select((question, index) => new
        {
            Id = Guid.Parse(
                $"{topicNumber}0000000-0000-0000-0000-{index + 6:000000000000}"),
            Topic = topic,
            question.Text,
            question.IdealAnswer
        });
    }

